const commands=$('Convex — načítaj príkazy').first().json.rows||[];
const rows=Array.isArray($json.values)?$json.values.map(row=>[...row]):[];
if(!rows.length||String(rows[0]?.[0]||'')!=='Doklad ID')throw new Error('Register nemá očakávanú hlavičku Doklad ID');
if(commands.length>50)throw new Error('Príkazová dávka presahuje limit 50');
const clean=v=>String(v??'').trim();
const num=v=>{const s=clean(v).replace(/\s/g,'');const n=Number(s.includes(',')&&s.includes('.')?s.replace(/\./g,'').replace(',','.'):s.replace(',','.'));return Number.isFinite(n)?n:0};
const paid=s=>['uhradené','uhradene','paid','zaplatené','zaplatene'].includes(clean(s).toLocaleLowerCase('sk'));
const output=[];
for(const command of commands){
 const p=command.payload||{};let data=[];
 if(command.type==='ADD_PAYABLE'){
  const existing=rows.findIndex((row,index)=>index>0&&clean(row[0])===command.commandId);
  if(existing>=1){data=[{range:`Doklady!A${existing+1}`,majorDimension:'ROWS',values:[[command.commandId]]}]}
  else {
   const method=clean(p.paymentMethod);const autoPaid=['Platobná karta','Trvalý príkaz / paušál'].includes(method);
   const values=Array(37).fill('');
   Object.assign(values,{0:command.commandId,1:'WOF',2:clean(p.deliveryDate).slice(0,7),3:'Ručný záväzok',4:'Na kontrolu',5:new Date(command.createdAt).toISOString(),6:clean(p.invoiceDate),7:clean(p.deliveryDate),8:clean(p.dueDate),9:clean(p.supplier),13:clean(p.invoiceNumber),15:clean(p.currency),18:Number(p.amount),19:method,20:autoPaid?'Uhradené':'Neoverené',25:'dashboard',27:'Ručne zadané v dashboarde',31:clean(p.purpose),32:'MANUAL',33:'dashboard-n8n-v2',35:autoPaid?Number(p.amount).toFixed(2):'',36:autoPaid?`Automaticky uhradené · ${command.commandId}`:''});
   rows.push(values);data=[{range:`Doklady!A${rows.length}:AK${rows.length}`,majorDimension:'ROWS',values:[values]}];
  }
 } else if(command.type==='MARK_PAID'){
  const ids=[...new Set((p.documentIds||[]).map(clean).filter(Boolean))];
  const matches=rows.map((row,index)=>({row,index})).filter(x=>x.index>0&&ids.includes(clean(x.row[0])));
  if(matches.length!==ids.length)throw new Error(`Príkaz ${command.commandId}: niektorý doklad chýba`);
  for(const item of matches){
   const row=item.row;const history=clean(row[36]);
   if(history.includes(command.commandId)){data.push({range:`Doklady!U${item.index+1}`,majorDimension:'ROWS',values:[[clean(row[20])]]});continue}
   if(paid(row[20])||['platobná karta','trvalý príkaz / paušál'].includes(clean(row[19]).toLocaleLowerCase('sk')))throw new Error(`Príkaz ${command.commandId}: doklad je už uhradený`);
   const total=num(row[18]);const paidBefore=num(row[35]);const remaining=Math.max(0,total-paidBefore);const amount=p.amount==null?remaining:Number(p.amount);
   if(!Number.isFinite(amount)||amount<=0||!total||amount>remaining+0.005)throw new Error(`Príkaz ${command.commandId}: neplatná suma úhrady`);
   const paidTotal=Math.min(total,paidBefore+amount);const status=paidTotal>=total-0.005?'Uhradené':'Čiastočne uhradené';
   const ref=clean(p.reference);const note=clean(p.note);const audit=[clean(row[27]),`Úhrada ${amount.toFixed(2)} ${clean(row[15])}: ${clean(p.paymentDate)}`,ref?`Referencia: ${ref}`:'',note?`Poznámka: ${note}`:'',`Príkaz: ${command.commandId}`].filter(Boolean).join(' | ').slice(-5000);
   const entry=[clean(p.paymentDate),`${amount.toFixed(2)} ${clean(row[15])}`,ref?`ref. ${ref}`:'',note,command.commandId].filter(Boolean).join(' · ');
   const values=Array.from({length:17},(_,offset)=>row[20+offset]??'');values[0]=status;values[1]=ref?`Ručne: ${ref}`:`Ručne potvrdené ${clean(p.paymentDate)}`;values[7]=audit;values[15]=paidTotal.toFixed(2);values[16]=[history,entry].filter(Boolean).join(' | ').slice(-5000);
   for(let offset=0;offset<17;offset++)row[20+offset]=values[offset];
   data.push({range:`Doklady!U${item.index+1}:AK${item.index+1}`,majorDimension:'ROWS',values:[values]});
  }
 } else throw new Error(`Nepodporovaný typ príkazu: ${command.type}`);
 output.push({json:{commandId:command.commandId,attempt:command.attempts,body:{valueInputOption:'RAW',data}}});
}
return output;
